import { useMemo } from 'react';

const range = (start: number, end: number) => {
  const length = end - start + 1;
  return Array.from({ length }, (_, idx) => idx + start);
};

export const usePagination = ({
  totalCount,
  pageSize,
  currentPage,
}: {
  totalCount: number;
  pageSize: number;
  currentPage: number;
}): number[] => {
  const paginationRange = useMemo(() => {
    const totalPageCount = Math.ceil(totalCount / pageSize);

    const totalPageNumbers = 5;

    if (totalPageNumbers >= totalPageCount) {
      return range(1, totalPageCount);
    }

    if (currentPage === 1 || currentPage === 2) return range(1, 5);
    if (currentPage === totalPageCount || currentPage === totalPageCount - 1) {
      return range(totalPageCount - 4, totalPageCount);
    }

    const leftSiblingIndex = Math.max(currentPage - 2, 1);
    const rightSiblingIndex = Math.min(currentPage + 2, totalPageCount);

    const middleRange = range(leftSiblingIndex, rightSiblingIndex);

    return middleRange;
  }, [totalCount, pageSize, currentPage]);
  return paginationRange;
};
